    if 1 in pos:
        r, c = pos[1]
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    # The 2, 3, and 6 make straight paths of their respective lengths.
    paths = {}
    if 2 in pos:
        r, c = pos[2]
        paths[2] = [(r, c - d) for d in range(1, 5)]
        for d in range(1, 5):
